void mainScreenViewBase::buttonCallbackHandler(const touchgfx::AbstractButton& src)
{
    if (&src == &btnMenu)
    {
        //Interaction_menu
        //When btnMenu clicked change screen to menuScreen
        //Go to menuScreen with no screen transition
        application().gotomenuScreenScreenNoTransition();
    }
    if (&src == &btnGraphCO2)
    {
        //InteractionCO2Graph
        //When btnGraphCO2 clicked change screen to co2Screen
        //Go to co2Screen with no screen transition
        application().gotoco2ScreenScreenNoTransition();
    }
    if (&src == &btnGraphCO)
    {
        //InteractionCOGraph
        //When btnGraphCO clicked change screen to coScreen
        //Go to coScreen with no screen transition
        application().gotocoScreenScreenNoTransition();
    }
    if (&src == &btnGraphO2)
    {
        //InteractionO2Graph
        //When btnGraphO2 clicked change screen to o2Screen
        //Go to o2Screen with no screen transition
        application().gotoo2ScreenScreenNoTransition();
    }
}
